#include "Acp/StudioKit/UnrealAgentStudioKitPrivate.h"

namespace UnrealAgentStudioKit
{
    FString MakeProjectSetupTemplateDisciplineSkill()
    {
        return MakeSkillMarkdown(
            TEXT("unreal-project-setup-template-discipline"),
            TEXT("Plan Unreal templates, project defaults, first maps, starter content, and content migration with MCP evidence."),
            TEXT("# Unreal Project Setup And Template Discipline\n\nUse this before choosing or changing template-derived defaults, Blueprint versus C++ project shape, starter or sample content, target platform or quality preset, default editor/game maps, Maps & Modes, GameMode or GameInstance defaults, input scaffolding, first-map setup, enabled plugins/modules, engine association, or content migration into a project. Treat Epic documentation as the setup model, not proof of current project state. Official anchors: Create your First Project (https://dev.epicgames.com/documentation/en-us/unreal-engine/create-your-first-project-in-unreal-engine), Working with Projects and Templates (https://dev.epicgames.com/documentation/en-us/unreal-engine/working-with-projects-and-templates-in-unreal-engine), Project Settings (https://dev.epicgames.com/documentation/en-us/unreal-engine/project-section-of-the-unreal-engine-project-settings), and Migrating Assets (https://dev.epicgames.com/documentation/en-us/unreal-engine/migrating-assets-in-unreal-engine).\n\nRequired discipline:\n- Run /unreal-tool-inventory, then inspect project and engine context, system_control get_project_settings read-back, current and default maps, Maps & Modes, GameMode/Default Pawn/PlayerController/HUD/GameState/GameInstance defaults, enabled plugins/modules, input setup, target platform and quality/scalability preset, Content Browser state through get_content_browser_state, starter/sample or migrated content, dependencies, dirty packages, source-control risk, restart requirements, and recent logs.\n- State the setup route: desired starting project shape, template or existing-project baseline, exact setting/map/content targets, system_control get_project_settings before set_project_setting, manage_level/manage_level_structure route for map creation/loading/saving, supported manage_asset route for package/import work, control_editor route for opening and saving, expected dirty files/packages, approval needs, validation, and rollback.\n- Keep template defaults, engine feature examples, Starter Content, Fab or sample-project content, migrated project content, and authored production content distinct. Do not copy Content directories, .uasset files, or .umap files with shell/filesystem tools; preserve dependency closure and canonical /Game package paths, and mark migration blocked when the connected MCP surface cannot perform the required package operation.\n- Ask before changing default maps or modes, replacing template GameMode/Pawn/input defaults, enabling plugins that require restart, changing engine association or target platform, adding large sample/starter content, migrating dependency trees, overwriting existing assets, or changing shared source-controlled project settings.\n- After mutation, read settings back through MCP, verify map existence and load/open state, save touched settings/maps/assets, inspect Content Browser paths and dependencies, compile affected Blueprints or C++, restart only when approved and required, run PIE for startup map/GameMode/Pawn/input behavior, review logs, and record exact settings, assets, maps, reports, and residual migration/package risk.\n- If MCP cannot inspect project settings, maps, plugins, or Content Browser state, state project setup is unverified and limit work to source/config/docs/log analysis. Do not claim a template, default map, GameMode, plugin, migrated dependency set, or first-playable startup path from file presence alone."));
    }

    FString MakeDiagnosticsCrashRecoveryDisciplineSkill()
    {
        return MakeSkillMarkdown(
            TEXT("unreal-diagnostics-crash-recovery-discipline"),
            TEXT("Diagnose Unreal crashes, asserts, ensures, compiler errors, build failures, log errors, and runtime regressions with MCP evidence."),
            TEXT("# Unreal Diagnostics And Crash Recovery Discipline\n\nUse this before diagnosing or fixing editor crashes, packaged-game crashes, fatal errors, asserts, ensures, editor hangs, PIE runtime errors, Blueprint compiler failures, Message Log or Output Log errors, asset load failures, missing references, packaging/cook/build failures, UBT errors, Python/console automation failures, plugin startup failures, or suspected regressions. Official anchors: Logging in Unreal (https://dev.epicgames.com/documentation/en-us/unreal-engine/logging-in-unreal-engine), Crash Reporting (https://dev.epicgames.com/documentation/en-us/unreal-engine/crash-reporting-in-unreal-engine), Blueprint Debugger (https://dev.epicgames.com/documentation/en-us/unreal-engine/blueprint-debugger-in-unreal-engine), and Run Automation Tests (https://dev.epicgames.com/documentation/unreal-engine/run-automation-tests-in-unreal-engine).\n\nRequired discipline:\n- Run /unreal-tool-inventory, then collect a baseline with exact error text, call stack, crash report path from Saved/Crashes when present, Saved/Logs or Output Log path, Message Log entries, reproduction step, map/project/PIE state, selected asset or Actor, Blueprint path and compile status when relevant, package/asset paths, dirty packages, target platform/configuration, command or MCP action that failed, and recent source/content/config changes.\n- Classify the failure before changing anything: crash/fatal/assert/ensure, hang/timeout, Blueprint compiler, C++/UBT, Python/console automation, asset load or missing reference, PIE/runtime gameplay, packaging/cook/build/deploy, editor UI/control, source-control/conflict, plugin/engine-version, or MCP/bridge transport. Keep these classes distinct so the validation route matches the symptom.\n- State the diagnostics route: hypothesis, exact evidence, narrow inspect action or current editor context needed, system_control route for run_tests/validate_assets/run_ubt/console_command/execute_python when applicable, manage_blueprint compile route for Blueprint failures, manage_asset validation route for asset/package failures, control_editor route for PIE or editor-state reproduction, approval needs, expected output/log/report paths, rollback, and stop condition.\n- Form two or three plausible hypotheses, then choose the smallest reversible fix. Do not clear caches, delete Intermediate/Saved/DerivedDataCache, reinstall or disable plugins, change engine association, bulk-fix redirectors, run destructive shell or source-control commands, or delete assets unless the user explicitly approves that recovery route after the exact risk is named.\n- After mutation, retest the original failure path first, then run the narrow validation: Blueprint compile/save plus fresh inspect for Blueprint issues, system_control run_tests for automation regressions, system_control validate_assets for package/asset issues, system_control run_ubt for C++ build failures, PIE start/stop plus runtime_report or pie_report for runtime bugs, and Output Log/Message Log review for all cases. The original exact error must be absent before claiming the fix.\n- Preserve diagnostic evidence: original error text, call stack or crash guid, log/crash/report paths, tool/action payload summary, command output, test counts, asset validation result, before/after relevant log lines, and remaining warnings. Distinguish warnings from blockers and state confidence limits.\n- If the crash or error cannot be reproduced, MCP is unavailable, logs are missing, or validation cannot run, state the diagnosis is unverified, name the missing evidence, and limit work to source/config/docs/log analysis."));
    }

    FString MakeOfficialGettingStartedSkill()
    {
        return MakeSkillMarkdown(
            TEXT("unreal-official-getting-started"),
            TEXT("Guide Unreal newcomers with Epic documentation anchors plus live MCP editor evidence."),
            TEXT("# Unreal Official Getting Started Loop\n\nUse this when the user asks how to get started with Unreal, wants a beginner tutorial, or needs the first editor session translated into concrete next actions. Treat Epic's documentation as conceptual anchors, not as proof of the user's current editor state. Official anchors: Create your First Project (https://dev.epicgames.com/documentation/unreal-engine/create-your-first-project-in-unreal-engine), Unreal Editor Interface (https://dev.epicgames.com/documentation/unreal-engine/unreal-editor-interface), Content Browser (https://dev.epicgames.com/documentation/unreal-engine/content-browser-in-unreal-engine), and In-Editor Testing / Play and Simulate (https://dev.epicgames.com/documentation/unreal-engine/in-editor-testing-play-and-simulate-in-unreal-engine).\n\nRequired sequence:\n1. Name the relevant official anchor for the user's question: project creation/template choice, editor interface, Content Browser asset organization, or PIE/SIE testing.\n2. Run /unreal-tool-inventory, then inspect the project, template or project type when observable, current level, viewport, selection, Content Browser state through get_content_browser_state, PIE state, dirty packages, and recent logs.\n3. Explain only the inspected editor surfaces in context: Project Browser/template, Level Editor viewport, Main Toolbar and Play controls, World Outliner, Details panel, Content Browser or Content Drawer, Output Log, and Message Log.\n4. Before changing anything, write an MCP route card with intent, evidence, tool/action, expected mutation, validation evidence, and rollback or stop condition.\n5. Make one small reversible MCP-backed change only if useful, then validate with save or compile, PIE or editor checks, fresh inspect, and logs. When PIE/SIE is used, explain that the preview session is not persistence proof until the editor/map/asset state is saved or kept and re-inspected after stop.\n\nIf MCP is unavailable, state that live editor state is unverified and limit the answer to official documentation concepts plus inspectable source, config, docs, or logs. Do not claim a panel location, selected asset, open level, project template, or PIE status from documentation alone."));
    }

    FString MakeEditorOrientationSkill()
    {
        return MakeSkillMarkdown(
            TEXT("unreal-editor-orientation"),
            TEXT("Guide a new or returning Unreal user through the current editor state with MCP-backed evidence."),
            TEXT("# Unreal Editor Orientation\n\nUse this when the user is new to Unreal, asks where or how to do something in the editor, or needs a first-project walkthrough. Start with /unreal-tool-inventory, then use MCP inspect to identify the project, template or project type when observable, current level, viewport, selection, Content Browser state, PIE state, and dirty packages. Explain the core surfaces in the context of what is actually open: Level Editor viewport, main toolbar and Play controls, World Outliner, Details panel, Content Browser or Content Drawer, Output Log, and Message Log. When selected folders or assets matter, call inspect with get_content_browser_state instead of guessing.\n\nFollow a practical first-session sequence: orient to the project and current level; demonstrate viewport navigation and selection; inspect assets and folders; place or select one Actor and explain its transform and components; save or compile the touched work; run PIE, stop it, and review logs; then propose one small reversible next milestone. Before any editor mutation, write an MCP route card and use the narrowest available domain tool. Prefer a live, tool-backed walkthrough over a generic tutorial dump. If MCP is unavailable, state that live editor state is unverified and give only source, configuration, or documentation-level guidance. Account for Unreal version differences and do not assert a panel location or state that was not inspected."));
    }

    FString MakeFirstPlayableLoopSkill()
    {
        return MakeSkillMarkdown(
            TEXT("unreal-first-playable-loop"),
            TEXT("Guide a beginner-friendly first playable Unreal editor loop while staying MCP-first and evidence-backed."),
            TEXT("# Unreal First Playable Editor Loop\n\nUse this when the user asks for a getting-started Unreal walkthrough, a first playable prototype, or help turning a new project/template into something they can run. Treat Epic's normal onboarding path as the shape of the work: identify the Project Browser/template context, orient the viewport and editor panels, use Content Browser or Content Drawer assets intentionally, place or modify one Actor, compile or save touched work, run Play In Editor, inspect logs, and capture evidence. Do not recite a generic tutorial when the editor can be inspected.\n\nRequired MCP-first sequence:\n1. Run /unreal-tool-inventory and confirm the connected unreal-engine MCP surface.\n2. Use inspect to capture project, level/map, viewport, selection, World Outliner, Details panel-relevant actor/component facts, Content Browser state through get_content_browser_state, PIE state, dirty packages, and recent logs.\n3. State a compact MCP route card before the first mutation: intent, evidence, chosen parent tool/action, expected editor or asset change, validation evidence, and rollback or stop condition.\n4. Make the smallest reversible first-playable change with MCP domain tools: control_actor or manage_level for placement, manage_blueprint or manage_asset for content, control_editor for viewport/PIE/screenshots, and system_control for compile, automation, logs, or build checks. Never hand-edit .uasset or .umap files.\n5. Validate by saving or compiling touched assets when relevant, running PIE if possible, stopping PIE cleanly, inspecting runtime/editor state, checking Output Log or Message Log evidence, and recording what is still unverified. Treat PIE/SIE preview-world changes as transient until save, compile, Keep Simulation Changes, and fresh post-stop inspect/log evidence prove persistence.\n\nIf MCP is unavailable, be explicit that live editor state is unverified. In that fallback, use source, config, docs, and logs only; give a safe checklist and ask the user to enable the bridge before claiming editor facts or mutating assets."));
    }

    FString MakePrototypeSkill()
    {
        return MakeSkillMarkdown(
            TEXT("unreal-prototype"),
            TEXT("Create the smallest playable Unreal loop before expanding into a full game."),
            TEXT("# Unreal Prototype Loop\n\nImplement one controllable player loop, one win/lose or progress signal, one feedback channel, and one validation route. Prefer reusable C++/Blueprint boundaries and clear asset names. After each change, compile or inspect the touched assets, run PIE when possible, and capture evidence before expanding scope."));
    }

    FString MakeValidationSkill()
    {
        return MakeSkillMarkdown(
            TEXT("unreal-validation-loop"),
            TEXT("Validate Unreal Agent changes with editor, MCP, logs, screenshots, tests, and evidence ledger entries."),
            TEXT("# Unreal Validation Loop\n\nBefore approval, state what must be true. Validate with the strongest available evidence: MCP `inspect`, Blueprint compile, PIE/run checks, automation tests, screenshots for visual work, log scans, profiling, build/package output, and source-control diff review. Save concise evidence and residual risks. If validation cannot run, say exactly why and what remains unproven."));
    }

    FString MakeReleaseSkill()
    {
        return MakeSkillMarkdown(
            TEXT("unreal-release-readiness"),
            TEXT("Check whether an Unreal project or feature is ready to package, ship, or hand off."),
            TEXT("# Unreal Release Readiness\n\nCheck packaging settings, target platforms, maps, inputs, scalability, save compatibility, crash/log risk, localization/accessibility, performance budgets, multiplayer assumptions, content redirects, test coverage, documentation, changelog, known issues, and source-control cleanliness. Separate blockers from warnings and record the evidence used."));
    }

    FString MakeDebugFixSkill()
    {
        return MakeSkillMarkdown(
            TEXT("unreal-debug-fix"),
            TEXT("Diagnose Unreal editor, asset, gameplay, build, or runtime failures using a baseline-fix-retest loop."),
            TEXT("# Unreal Debug Fix\n\nReproduce or collect the baseline first: exact error text, logs, asset path, map, platform, and recent changes. Form one narrow hypothesis, make the smallest fix, then retest the original failure. Preserve user changes and avoid broad cleanup unless it is required for the verified fix."));
    }

    FString MakeCppUObjectLifecycleSkill()
    {
        return MakeSkillMarkdown(
            TEXT("unreal-cpp-uobject-lifecycle-integrity"),
            TEXT("Check Unreal C++ UObject, reflection, CDO, GC, delegate, timer, async, and subsystem safety before implementation claims."),
            TEXT("# Unreal C++ UObject Lifecycle Integrity\n\nUse this before changing or judging Unreal C++ involving UCLASS/USTRUCT/UENUM/UFUNCTION/UPROPERTY, CDO/defaults, constructors, BeginPlay/PostInitProperties/PostLoad, subsystem lifetime, GC ownership, soft references, async work, delegates, timers, replication, or Blueprint exposure.\n\nRequired discipline:\n- Confirm reflected fields use UPROPERTY or intentional non-reflected storage.\n- Keep constructor work CDO-safe; avoid world, asset, and actor assumptions before runtime hooks.\n- Bind delegates and timers with explicit unbind/clear ownership.\n- Keep UObject access on the game thread unless a documented engine API says otherwise.\n- Prefer soft paths and validated loads for assets; do not assume editor-only assets exist at runtime.\n- Verify with compile, logs, MCP inspection, PIE/runtime checks, or explain what remains unverified."));
    }
}
